function x(r){if(r===null||r.trim()==="")return null;let n=Number(r);return Number.isFinite(n)?n:null}function m(r,n,e){return Math.min(Math.max(r,n),e)}function l(r,n,e){return n<=0?e.left:e.left+m(r,0,n)/n*(e.right-e.left)}function o(r,n,e,u,f,t){if(n===null)return null;if(r===null){let h=l(n,e,u);return{x:m(h-t/2,u.left,u.right-t),width:t}}let b=l(Math.min(r,n),e,u),c=l(Math.max(r,n),e,u),i=Math.max(c-b,f);return{x:m(b,u.left,u.right-i),width:i}}function p(r,n,e){return Math.max(e.left,Math.min(r,e.right-n))}export{o as barSpan,x as parseValue,l as scaleX,p as tagStart};
